-- Seed the weekly availability for Moarz, Martin, Lulu, Hsu, Su and Tina from the old availability sheet.
-- Run in the Supabase SQL editor. Safe to re-run (it replaces those people's weekly grids).
-- Sheet blocks marked "1" are busy; everything else 9 am - 10 pm is free; 8-9 am and 10-11 pm are left busy.
with data(who, cells) as (values
  ('Moarz', '001100000000110000111111111100001100001111111100000000000000000000111111111111111111111100001111111111111100000000000000001100001111111111111111111100001111111111111111111111111100001111111111111111111111111100'),
  ('Martin', '001100110011000011111111111100001111111111110000111111111100001111000011001111001111111100000000111100000011111111111100001111111100001111111111111100001100000011111111111111111100001111111111111111111111111100'),
  ('Lulu', '001111000011111111111100111100000000111100001111111111111100001111111111111111000011111100001111111111111111000011111100001100000000001111111111111100001111111111111111111111111100001111111111111111111111111100'),
  ('Su', '001111111100000000001111111100000000000000000000000000000000001111000000000000000000111100001111000000111100000000000000000000000000110000000000000000000000000000000000000000000000001111111111001111111111111100'),
  ('Tina', '001111111111001111111111111100000000111111111111111111111100000000000000000000111111111100001111111100000011111111111100001111110011000000111111111100001111111111111111111111111100001111111111111111111111111100'),
  ('Hsu', '000000000000001111111111111100000000000000000000000000000000000000000011111111111111111100000000000000000011111111111100001111111100000000000000000000001111111111111111111111111100001111111111111111111111111100')
),
ins as (
  insert into public.availability (user_id, cells, updated_at)
  select p.id, d.cells, now()
  from data d
  join public.profiles p on lower(p.display_name) = lower(d.who)
  on conflict (user_id) do update set cells = excluded.cells, updated_at = now()
  returning user_id
)
select p.display_name as seeded
from ins join public.profiles p on p.id = ins.user_id
order by p.display_name;
